import { UriTemplateError, parse } from './parse.js';

const UNRESERVED_RE = /[A-Za-z0-9\-._~]/;
const RESERVED_CHARS = ":/?#[]@!$&'()*+,;=";
const HEX_RE = /[0-9A-Fa-f]/;

function isUnreserved(ch) {
  return UNRESERVED_RE.test(ch);
}

function isReserved(ch) {
  return RESERVED_CHARS.includes(ch);
}

function encodeCodePointBytes(ch) {
  const bytes = Buffer.from(ch, 'utf8');
  let out = '';
  for (const byte of bytes) {
    out += `%${byte.toString(16).toUpperCase().padStart(2, '0')}`;
  }
  return out;
}

/** Encode preserving unreserved characters, reserved characters and existing percent-triplets. */
function encodeReserved(str) {
  const chars = Array.from(str);
  let out = '';
  for (let i = 0; i < chars.length; i += 1) {
    const ch = chars[i];
    if (ch === '%' && chars[i + 1] !== undefined && chars[i + 2] !== undefined
      && HEX_RE.test(chars[i + 1]) && HEX_RE.test(chars[i + 2])) {
      out += `%${chars[i + 1]}${chars[i + 2]}`;
      i += 2;
      continue;
    }
    if (isUnreserved(ch) || isReserved(ch)) {
      out += ch;
    } else {
      out += encodeCodePointBytes(ch);
    }
  }
  return out;
}

/** Encode keeping only unreserved characters; everything else (including `%`) is percent-encoded. */
function encodeUnreserved(str) {
  let out = '';
  for (const ch of Array.from(str)) {
    if (isUnreserved(ch)) {
      out += ch;
    } else {
      out += encodeCodePointBytes(ch);
    }
  }
  return out;
}

function encodeValue(str, reservedEncoding) {
  return reservedEncoding ? encodeReserved(str) : encodeUnreserved(str);
}

const OPERATORS = {
  '': { prefix: '', sep: ',', named: false, ifemp: '', reservedEncoding: false },
  '+': { prefix: '', sep: ',', named: false, ifemp: '', reservedEncoding: true },
  '#': { prefix: '#', sep: ',', named: false, ifemp: '', reservedEncoding: true },
  '.': { prefix: '.', sep: '.', named: false, ifemp: '', reservedEncoding: false },
  '/': { prefix: '/', sep: '/', named: false, ifemp: '', reservedEncoding: false },
  ';': { prefix: ';', sep: ';', named: true, ifemp: '', reservedEncoding: false },
  '?': { prefix: '?', sep: '&', named: true, ifemp: '=', reservedEncoding: false },
  '&': { prefix: '&', sep: '&', named: true, ifemp: '=', reservedEncoding: false },
};

function isValidScalar(value) {
  if (typeof value === 'string' || typeof value === 'boolean') return true;
  if (typeof value === 'number' && Number.isFinite(value)) return true;
  return false;
}

function scalarToString(value, name) {
  if (!isValidScalar(value)) {
    throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
  }
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  return String(value);
}

function truncate(str, maxLength) {
  if (maxLength === null) return str;
  return Array.from(str).slice(0, maxLength).join('');
}

/**
 * Expand a template against a set of variables.
 *
 * @param {string} template template text
 * @param {Record<string, unknown>} variables values bound by name, read as own properties
 * @returns {string} the expanded URI
 */
export function expand(template, variables) {
  if (variables === null || typeof variables !== 'object' || Array.isArray(variables)) {
    throw new UriTemplateError('variables must be an object');
  }

  const parts = parse(template);
  let result = '';

  for (const part of parts) {
    if (part.type === 'literal') {
      result += encodeReserved(part.value);
    } else {
      result += expandExpression(part, variables);
    }
  }

  return result;
}

function expandExpression(expression, variables) {
  const config = OPERATORS[expression.operator];
  const pieces = [];

  for (const varSpec of expression.variables) {
    const varPieces = expandVariable(varSpec, variables, config);
    pieces.push(...varPieces);
  }

  if (pieces.length === 0) return '';
  return config.prefix + pieces.join(config.sep);
}

function expandVariable(varSpec, variables, config) {
  const { name, explode, maxLength } = varSpec;

  if (!Object.prototype.hasOwnProperty.call(variables, name)) return [];
  const value = variables[name];
  if (value === null || value === undefined) return [];

  if (Array.isArray(value)) {
    const usable = value.filter((v) => v !== null && v !== undefined);
    if (usable.length === 0) return [];
    if (maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
    }
    return expandArray(usable, name, explode, config);
  }

  if (typeof value === 'object') {
    const entries = Object.keys(value)
      .map((k) => [k, value[k]])
      .filter(([, v]) => v !== null && v !== undefined);
    if (entries.length === 0) return [];
    if (maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
    }
    return expandObject(entries, name, explode, config);
  }

  // scalar
  let str = scalarToString(value, name);
  str = truncate(str, maxLength);
  const encoded = encodeValue(str, config.reservedEncoding);
  return [namedPiece(name, encoded, config)];
}

function namedPiece(name, encodedValue, config) {
  if (!config.named) return encodedValue;
  if (encodedValue === '') return `${name}${config.ifemp}`;
  return `${name}=${encodedValue}`;
}

function expandArray(usable, name, explode, config) {
  const encodedItems = usable.map((v) => encodeValue(scalarToString(v, name), config.reservedEncoding));
  if (explode) {
    return encodedItems.map((item) => namedPiece(name, item, config));
  }
  const joined = encodedItems.join(',');
  return [namedPiece(name, joined, config)];
}

function expandObject(entries, name, explode, config) {
  const encodedPairs = entries.map(([k, v]) => [
    encodeValue(k, config.reservedEncoding),
    encodeValue(scalarToString(v, name), config.reservedEncoding),
  ]);

  if (explode) {
    return encodedPairs.map(([k, v]) => {
      if (config.named) {
        return v === '' ? `${k}${config.ifemp}` : `${k}=${v}`;
      }
      return `${k}=${v}`;
    });
  }

  const joined = encodedPairs.flatMap(([k, v]) => [k, v]).join(',');
  return [namedPiece(name, joined, config)];
}
